# Gritty Neon Poster Layout

Here's a bold, intentional design that turns those underexposed photos into a feature, not a bug. The layout embraces controlled chaos with aggressive overlapping type and semi-transparent neon blocks.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>NEON VOID - Show Poster</title>
  <link href="https://fonts.googleapis.com/css2?family=Anton&family=Space+Mono:wght@400;700&display=swap" rel="stylesheet">
  <style>
    /* ========================================
       COLOR PALETTE
       ======================================== */
    :root {
      --void-black:    #050505;
      --deep-charcoal: #0f0f0f;
      --neon-magenta:  #ff0066;
      --electric-cyan: #00fff7;
      --toxic-lime:    #c8ff00;
      --burnt-orange:  #ff4d00;
      --ghost-white:  #f0f0f0;
    }

    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }

    body {
      background: var(--void-black);
      min-height: 100vh;
      display: flex;
      justify-content: center;
      align-items: center;
      padding: 2rem;
      font-family: 'Space Mono', monospace;
    }

    /* ========================================
       POSTER CONTAINER
       ======================================== */
    .poster {
      width: 100%;
      max-width: 600px;
      aspect-ratio: 2/3;
      background: var(--void-black);
      position: relative;
      overflow: hidden;
      box-shadow: 
        0 0 60px rgba(255, 0, 102, 0.3),
        0 0 120px rgba(0, 255, 247, 0.15);
    }

    /* ========================================
       GRAIN TEXTURE OVERLAY (SVG)
       ======================================== */
    .grain-overlay {
      position: absolute;
      inset: 0;
      z-index: 100;
      pointer-events: none;
      opacity: 0.4;
      mix-blend-mode: overlay;
    }

    /* ========================================
       IMAGE LAYER (simulated underexposed)
       ======================================== */
    .image-layer {
      position: absolute;
      inset: 0;
      background: 
        linear-gradient(180deg, 
          transparent 0%,
          rgba(5, 5, 5, 0.3) 40%,
          rgba(5, 5, 5, 0.8) 70%,
          var(--void-black) 100%
        ),
        url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 600"><rect fill="%23080808" width="400" height="600"/><circle cx="200" cy="250" r="120" fill="%231a1a1a"/><ellipse cx="200" cy="400" rx="80" ry="150" fill="%23141414"/></svg>');
      background-size: cover;
      filter: brightness(0.6) contrast(1.3);
    }

    /* ========================================
       SEMI-TRANSPARENT COLOR BLOCKS
       ======================================== */
    .color-block {
      position: absolute;
      mix-blend-mode: screen;
    }

    .block-magenta {
      top: 15%;
      left: -10%;
      width: 70%;
      height: 35%;
      background: rgba(255, 0, 102, 0.25);
      transform: skewY(-6deg);
    }

    .block-cyan {
      top: 40%;
      right: -15%;
      width: 80%;
      height: 25%;
      background: rgba(0, 255, 247, 0.15);
      transform: skewY(4deg);
    }

    .block-lime {
      bottom: 20%;
      left: 5%;
      width: 40%;
      height: 15%;
      background: rgba(200, 255, 0, 0.12);
      transform: skewX(-8deg);
    }

    /* ========================================
       TYPOGRAPHY - MAIN HEADLINE
       ======================================== */
    .headline {
      font-family: 'Anton', sans-serif;
      text-transform: uppercase;
      position: absolute;
      line-height: 0.85;
      letter-spacing: -0.02em;
    }

    .headline-main {
      font-size: clamp(4rem, 18vw, 11rem);
      top: 8%;
      left: -2%;
      color: var(--ghost-white);
      text-shadow: 
        4px 4px 0 var(--neon-magenta),
        -2px -2px 0 var(--electric-cyan);
      z-index: 20;
      mix-blend-mode: normal;
    }

    .headline-main span {
      display: block;
    }

    .headline-main .line-2 {
      margin-left: 25%;
      color: transparent;
      -webkit-text-stroke: 3px var(--ghost-white);
      text-shadow: none;
    }

    /* ========================================
       OVERLAPPING SUB-HEADLINE
       ======================================== */
    .sub-headline {
      font-size: clamp(2.5rem, 12vw, 7rem);
      top: 38%;
      right: -5%;
      color: var(--neon-magenta);
      transform: rotate(-90deg);
      transform-origin: right center;
      z-index: 15;
      opacity: 0.9;
    }

    /* ========================================
       GLITCH TEXT EFFECT
       ======================================== */
    .glitch-text {
      font-size: clamp(1.2rem, 4vw, 2rem);
      top: 55%;
      left: 8%;
      color: var(--electric-cyan);
      z-index: 25;
      font-family: 'Space Mono', monospace;
      font-weight: 700;
      letter-spacing: 0.3em;
      text-transform: uppercase;
    }

    .glitch-text::before,
    .glitch-text::after {
      content: attr(data-text);
      position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
    }

    .glitch-text::before {
      color: var(--neon-magenta);
      animation: glitch-1 2s infinite linear alternate-reverse;
      clip-path: polygon(0 0, 100% 0, 100% 35%, 0 35%);
    }

    .glitch-text::after {
      color: var(--toxic-lime);
      animation: glitch-2 3s infinite linear alternate-reverse;
      clip-path: polygon(0 65%, 100% 65%, 100% 100%, 0 100%);
    }

    @keyframes glitch-1 {
      0%, 90%, 100% { transform: translate(0); }
      92% { transform: translate(-3px, 1px); }
      94% { transform: translate(3px, -1px); }
      96% { transform: translate(-2px, 2px); }
    }

    @keyframes glitch-2 {
      0%, 88%, 100% { transform: translate(0); }
      90% { transform: translate(2px, -1px); }
      93% { transform: translate(-3px, 2px); }
      96% { transform: translate(1px, -2px); }
    }

    /* ========================================
       DATE & VENUE INFO
       ======================================== */
    .info-block {
      position: absolute;
      bottom: 8%;
      left: 5%;
      right: 5%;
      z-index: 30;
    }

    .date-line {
      font-size: clamp(3rem, 10vw, 5.5rem);
      font-family: 'Anton', sans-serif;
      color: var(--toxic-lime);
      line-height: 1;
      margin-bottom: 0.5rem;
    }

    .venue-line {
      font-size: clamp(0.7rem, 2vw, 0.9rem);
      color: var(--ghost-white);
      letter-spacing: 0.15em;
      text-transform: uppercase;
      opacity: 0.8;
    }

    .venue-line span {
      color: var(--neon-magenta);
    }

    /* ========================================
       DECORATIVE ELEMENTS
       ======================================== */
    .deco-line {
      position: absolute;
      background: var(--electric-cyan);
      height: 2px;
      width: 60%;
      right: 0;
      top: 65%;
      z-index: 10;
      opacity: 0.6;
    }

    .deco-box {
      position: absolute;
      border: 1px solid var(--neon-magenta);
      width: 15%;
      aspect-ratio: 1;
      bottom: 25%;
      right: 8%;
      z-index: 10;
      opacity: 0.5;
      transform: rotate(15deg);
    }

    .barcode {
      position: absolute;
      bottom: 5%;
      right: 5%;
      width: 25%;
      height: 3%;
      z-index: 30;
      opacity: 0.7;
    }

    /* ========================================
       FLOATING TEXT LAYER
       ======================================== */
    .floating-text {
      position: absolute;
      font-family: 'Space Mono', monospace;
      font-size: 0.6rem;
      color: rgba(255, 255, 255, 0.3);
      writing-mode: vertical-rl;
      text-orientation: mixed;
      letter-spacing: 0.5em;
      z-index: 5;
    }

    .float-1 {
      top: 20%;
      left: 3%;
      height: 40%;
    }

    .float-2 {
      top: 10%;
      right: 4%;
      height: 50%;
      color: rgba(0, 255, 247, 0.2);
    }

    /* ========================================
       RESPONSIVE & PRINT STYLES
       ======================================== */
    @media (max-width: 480px) {
      body {
        padding: 1rem;
      }

      .sub-headline {
        font-size: clamp(2rem, 10vw, 4rem);
      }
    }

    @media print {
      body {
        background: var(--void-black);
      }

      .poster {
        box-shadow: none;
      }
    }

    /* Reduced motion */
    @media (prefers-reduced-motion: reduce) {
      .glitch-text::before,
      .glitch-text::after {
        animation: none;
      }
    }
  </style>
</head>
<body>

  <article class="poster" role="img" aria-label="Concert poster for Neon Void show">

    <!-- Grain Texture SVG -->
    <svg class="grain-overlay" viewBox="0 0 200 200" preserveAspectRatio="none">
      <filter id="noise">
        <feTurbulence type="fractalNoise" baseFrequency="0.9" numOctaves="4" stitchTiles="stitch"/>
        <feColorMatrix type="saturate" values="0"/>
      </filter>
      <rect width="100%" height="100%" filter="url(#noise)"/>
    </svg>

    <!-- Image Layer (replace SVG with actual photo) -->
    <div class="image-layer"></div>

    <!-- Semi-Transparent Color Blocks -->
    <div class="color-block block-magenta"></div>
    <div class="color-block block-cyan"></div>
    <div class="color-block block-lime"></div>

    <!-- Main Headline -->
    <h1 class="headline headline-main">
      <span class="line-1">NEON</span>
      <span class="line-2">VOID</span>
    </h1>

    <!-- Overlapping Sub-Headline -->
    <span class="headline sub-headline" aria-hidden="true">LIVE</span>

    <!-- Glitch Effect Text -->
