        <div class="swatch__info">
          <span class="swatch__name">Neon Magenta</span>
          <span class="swatch__hex">#ff0066</span>
        </div>
      </div>
      <div class="swatch">
        <div class="swatch__color" style="background: #d4ff00;"></div>
        <div class="swatch__info">
          <span class="swatch__name">Neon Yellow</span>
          <span class="swatch__hex">#d4ff00</span>
        </div>
      </div>
      <div class="swatch">
        <div class="swatch__color" style="background: #ff4400;"></div>
        <div class="swatch__info">
          <span class="swatch__name">Neon Orange</span>
          <span class="swatch__hex">#ff4400</span>
        </div>
      </div>
      <div class="swatch">
        <div class="swatch__color" style="background: #05050a;"></div>
