<span class="comment">/* Yellow block */</span>
<span class="property">background</span>: <span class="value">rgba(212, 255, 0, 0.1)</span>;
<span class="property">border-right</span>: <span class="value">2px solid #d4ff00</span>;</div>

    <h2>Overlapping Type CSS</h2>
    <div class="code-block"><span class="comment">/* Main headline line */</span>
<span class="property">font-family</span>: <span class="value">'Bebas Neue', sans-serif</span>;
<span class="property">font-size</span>: <span class="value">clamp(4rem, 18vw, 9rem)</span>;
<span class="property">line-height</span>: <span class="value">0.85</span>;
<span class="property">letter-spacing</span>: <span class="value">-0.02em</span>;
<span class="property">mix-blend-mode</span>: <span class="value">hard-light</span>;

<span class="comment">/* Text shadow stacking */</span>
