              -1px -1px 0 #05050a</span>;

<span class="comment">/* Exclusion blend for crossing */</span>
<span class="property">mix-blend-mode</span>: <span class="value">exclusion</span>;</div>

    <h2>SVG Noise Filter</h2>
    <div class="code-block"><span class="comment">&lt;!-- SVG noise overlay --&gt;</span>
&lt;<span class="property">svg</span> viewBox="<span class="value">0 0 200 300</span>"&gt;
  &lt;<span class="property">filter</span> id="<span class="value">noise-filter</span>"&gt;
    &lt;<span class="property">feTurbulence</span> 
      type="<span class="value">fractalNoise</span>" 
