go 1.21

require (
    github.com/go-chi/chi/v5 v5.0.10 // Lightweight router, faster than standard mux
)
```

#### 2. `internal/model/model.go`
Defining structs is far more memory-efficient than Node's dynamic objects.
```go
package model

// UserResponse matches your contract test schema
type UserResponse struct {
    ID    string `json:"id"`
    Name  string `json:"name"`
    Email string `json:"email"`
}

// ErrorResponse standardizes API errors
type ErrorResponse struct {
    Error   string `json:"error"`
    Code    int    `json:"code"`
    Details string `json:"details,omitempty"`
}
```

#### 3. `internal/handler/handler.go`
We avoid global variables to ensure clean memory scoping.
```go
package handler

import (
    "encoding/json"
    "net/http"

    "github.com/go-chi/chi/v5"
    "github.com/yourorg/high-traffic-service/internal/model"
)

// Handler holds dependencies (DB pools, loggers, etc.)
// This struct replaces the 'global' state often seen in Node apps.
type Handler struct {
    // db *sql.DB
    // cache *redis.Client
}

func NewHandler() *Handler {
    return &Handler{}
}

func (h *Handler) RegisterRoutes(r chi.Router) {
    r.Get("/users/{id}", h.GetUser)
    r.Get("/health", h.HealthCheck)
}

func (h *Handler) GetUser(w http.ResponseWriter, r *http.Request) {
    id := chi.URLParam(r, "id")

    // MOCK LOGIC: Replace with actual DB call
    // In Node, high memory often comes from creating large objects inside loops.
    // Here, we use stack allocation where possible.
    if id == "" {
        renderError(w, http.StatusBadRequest, "Invalid ID")
        return
    }

    user := model.UserResponse{
        ID:    id,
        Name:  "Jane Doe",
        Email: "jane@example.com",
    }

    renderJSON(w, http.StatusOK, user)
}

func (h *Handler) HealthCheck(w http.ResponseWriter, r *http.Request) {
    w.WriteHeader(http.StatusOK)
    w.Write([]byte("OK"))
}

// Helper to render JSON without reflection overhead in hot paths
func renderJSON(w http.ResponseWriter, status int, payload interface{}) {
    w.Header().Set("Content-Type", "application/json")
    w.WriteHeader(status)

    // json.NewEncoder uses less memory allocation than json.Marshal 
    // for large payloads as it streams directly to the writer.
    if err := json.NewEncoder(w).Encode(payload); err != nil {
        http.Error(w, "Failed to encode response", http.StatusInternalServerError)
    }
}

func renderError(w http.ResponseWriter, code int, message string) {
    renderJSON(w, code, model.ErrorResponse{
        Error: message,
        Code:  code,
    })
}
```

#### 4. `cmd/server/main.go`
This setup implements **Graceful Shutdown**. This is critical for the cutover to prevent dropping in-flight requests when you stop the Node.js service or start the Go one.
```go
package main

import (
    "context"
    "log"
    "net/http"
    "os"
    "os/signal"
    "syscall"
    "time"

    "github.com/go-chi/chi/v5"
    "github.com/yourorg/high-traffic-service/internal/handler"
)

func main() {
    // 1. Setup Router and Handlers
    r := chi.NewRouter()

    // Middleware: Recover from panic (prevents process crash)
    r.Use(recoverer)

    h := handler.NewHandler()
    h.RegisterRoutes(r)

    // 2. Configure Server
    // Set reasonable timeouts to prevent memory leaks from slow/hung clients (Slowloris attacks)
    srv := &http.Server{
        Addr:         ":8080",
        Handler:      r,
        ReadTimeout:  5 * time.Second,
        WriteTimeout: 10 * time.Second,
        IdleTimeout:  120 * time.Second, // Crucial for high traffic to keep-alive efficiently
    }

    // 3. Start Server in a goroutine
    go func() {
        log.Println("Starting Go service on :8080")
        if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
            log.Fatalf("Server error: %v", err)
        }
    }()

    // 4. Graceful Shutdown Logic
    quit := make(chan os.Signal, 1)
    signal.Notify(quit, syscall.SIGINT, syscall.SIGTERM)
    <-quit

    log.Println("Shutting down service...")

    // Give 30 seconds for ongoing requests to finish
    ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
    defer cancel()

    if err := srv.Shutdown(ctx); err != nil {
        log.Fatalf("Server forced to shutdown: %v", err)
    }

    log.Println("Service exited cleanly")
}

// Simple recoverer middleware
func recoverer(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        defer func() {
            if rvr := recover(); rvr != nil {
                log.Printf("Panic recovered: %v", rvr)
                http.Error(w, http.StatusText(http.StatusInternalServerError), http.StatusInternalServerError)
            }
        }()
        next.ServeHTTP(w, r)
    })
}
```

