## Go Service Scaffold

```go
// main.go
package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/prometheus/client_golang/prometheus/promhttp"
)

type Config struct {
	Port            string
	ShutdownTimeout time.Duration
}

type Service struct {
	config  Config
	logger  *slog.Logger
	version string
	// Add your dependencies here (db connections, clients, etc.)
}

func main() {
	cfg := Config{
		Port:            getEnv("PORT", "8080"),
		ShutdownTimeout: 30 * time.Second,
	}

	logger := slog.New(slog.NewJSONHandler(os.Stdout, &slog.HandlerOptions{
		Level: slog.LevelInfo,
	}))

	svc := &Service{
		config:  cfg,
		logger:  logger,
		version: "1.0.0",
	}

	svc.run()
}

func (s *Service) run() {
	mux := http.NewServeMux()

	// Register your endpoints here
	mux.HandleFunc("GET /api/v1/resources", s.listResources)
	mux.HandleFunc("GET /api/v1/resources/{id}", s.getResource)
	mux.HandleFunc("POST /api/v1/resources", s.createResource)
	mux.HandleFunc("PUT /api/v1/resources/{id}", s.updateResource)
	mux.HandleFunc("DELETE /api/v1/resources/{id}", s.deleteResource)

	// Health and metrics
	mux.HandleFunc("/health", s.healthCheck)
	mux.HandleFunc("/ready", s.readinessCheck)
	mux.Handle("GET /metrics", promhttp.Handler())

	// Wrap with middleware
	handler := s.loggingMiddleware(s.recoveryMiddleware(handler))

	srv := &http.Server{
		Addr:         ":" + s.config.Port,
		Handler:      handler,
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 30 * time.Second,
		IdleTimeout:  120 * time.Second,
	}

	// Graceful shutdown
	go func() {
		sigCh := make(chan os.Signal, 1)
		signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)
		<-sigCh

		s.logger.Info("shutting down gracefully")
		ctx, cancel := context.WithTimeout(context.Background(), s.config.ShutdownTimeout)
		defer cancel()
		srv.Shutdown(ctx)
	}()

	s.logger.Info("starting server", "port", s.config.Port)
	if err := srv.ListenAndServe(); err != http.ErrServerClosed {
		s.logger.Error("server error", "error", err)
		os.Exit(1)
	}
}

// --- Handlers ---

type Resource struct {
	ID   string `json:"id"`
	Name string `json:"name"`
	// Add your resource fields
}

func (s *Service) listResources(w http.ResponseWriter, r *http.Request) {
	// TODO: Implement pagination, filtering
	resources := []Resource{
		{ID: "1", Name: "example"},
	}
	s.jsonResponse(w, http.StatusOK, resources)
}

func (s *Service) getResource(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id")
	// TODO: Fetch from your data store
	resource := Resource{ID: id, Name: "example"}
	s.jsonResponse(w, http.StatusOK, resource)
}

func (s *Service) createResource(w http.ResponseWriter, r *http.Request) {
	var req Resource
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		s.errorResponse(w, http.StatusBadRequest, "invalid request body")
		return
	}
	// TODO: Validate and persist
	req.ID = "generated-id"
	s.jsonResponse(w, http.StatusCreated, req)
}

func (s *Service) updateResource(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id")
	var req Resource
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		s.errorResponse(w, http.StatusBadRequest, "invalid request body")
		return
	}
	// TODO: Update in data store
	req.ID = id
	s.jsonResponse(w, http.StatusOK, req)
}

func (s *Service) deleteResource(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id")
	// TODO: Delete from data store
	s.logger.Info("deleting resource", "id", id)
	w.WriteHeader(http.StatusNoContent)
}

// --- Health Checks ---

func (s *Service) healthCheck(w http.ResponseWriter, r *http.Request) {
	s.jsonResponse(w, http.StatusOK, map[string]string{
		"status":  "healthy",
		"version": s.version,
	})
}

func (s *Service) readinessCheck(w http.ResponseWriter, r *http.Request) {
	// TODO: Check dependencies (db, cache, etc.)
	s.jsonResponse(w, http.StatusOK, map[string]string{
		"status": "ready",
	})
}

// --- Middleware ---

func (s *Service) loggingMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		rw := &responseWriter{ResponseWriter: w, status: http.StatusOK}
		next.ServeHTTP(rw, r)
		s.logger.Info("request",
			"method", r.Method,
			"path", r.URL.Path,
			"status", rw.status,
			"duration", time.Since(start).Milliseconds(),
		)
	})
}

func (s *Service) recoveryMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer func() {
			if err := recover(); err != nil {
				s.logger.Error("panic recovered", "error", err)
				s.errorResponse(w, http.StatusInternalServerError, "internal error")
			}
		}()
		next.ServeHTTP(w, r)
	})
}

// --- Helpers ---

type responseWriter struct {
	http.ResponseWriter
	status int
}

func (rw *responseWriter) WriteHeader(code int) {
	rw.status = code
	rw.ResponseWriter.WriteHeader(code)
}

func (s *Service) jsonResponse(w http.ResponseWriter, status int, data any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(data)
}

func (s *Service) errorResponse(w http.ResponseWriter, status int, message string) {
	s.jsonResponse(w, status, map[string]string{"error": message})
}

func getEnv(key, fallback string) string {
	if value := os.Getenv(key); value != "" {
		return value
	}
	return fallback
}
